  "final segment": "अंतिम खंड",
  "for the commands available on this page.": "इस पृष्ठ पर उपलब्ध कमांड के लिए।",
  "gate. You will see exactly what is captured before anything is sent.": "। भेजने से पहले आप देखेंगे कि क्या दर्ज होगा।",
  "healthy": "स्वस्थ",
  "is resolved server-side at dispatch and is never sent to a browser, so it cannot be read, replayed or edited from here — changing one is a server deployment.": "भेजते समय सर्वर पर तय होता है और ब्राउज़र को नहीं भेजा जाता; यहाँ से पढ़ना, दोबारा चलाना या बदलना संभव नहीं। बदलाव के लिए सर्वर पर तैनाती चाहिए।",
  "is worth showing: 20 because someone chose 20 and 20 because nothing is configured look identical in the number alone.": "दिखाना उपयोगी है: चुना गया 20 और सेटिंग न होने से आया 20 केवल संख्या से एक जैसे दिखते हैं।",
