  "api.message.a3905eb93e40": "आपने साइन इन नहीं किया है।",
  "api.message.6adae2229057": "अमान्य उत्पाद।",
  "api.message.c6e7afb093a6": "उत्पाद उपलब्ध नहीं है।",
  "api.message.f91c6aa194a1": "इस खाते के लिए कोई मेनू उपलब्ध नहीं है।",
  "api.message.55d7eb65faaa": "यह भाषा समर्थित नहीं है।",
  "api.message.1ebd2d43e7a1": "समर्थित उत्पाद और पृष्ठ चुनें।",
  "api.message.097943763f47": "आपकी भूमिका को अनुमोदन उपयोग करने की अनुमति नहीं है।",
  "api.message.3fc3fc0d5316": "कार्रवाई पहचानकर्ता आवश्यक है।",
  "api.message.e308d6ea7237": "यह कार्रवाई पहचानकर्ता पहले उपयोग हो चुका है।",
  "api.message.d5f87f5a90d3": "केवल प्रशासक अनुमोदन चरण निर्धारित कर सकते हैं।",
  "api.message.5df0e770bfb0": "सेटिंग बदल गई है। सहेजने से पहले रीफ़्रेश करें।",
  "api.message.a122b81f1ee3": "नाम वाले 1–5 चरण और कम से कम एक समर्थित अनुमोदक भूमिका चुनें।",
  "api.message.4a2f85e2749e": "सहेजा हुआ रिकॉर्ड चुनें।",
  "api.message.c8a74c7ae2a7": "पहले रिकॉर्ड सहेजें या मौजूदा रिकॉर्ड चुनें।",
  "api.message.cee9d59bb0c9": "अनुमोदन बदल गया है। भेजने से पहले रीफ़्रेश करें।",
  "api.message.433aafa9ce34": "केवल अनुरोधकर्ता यह रिकॉर्ड दोबारा भेज सकता है।",
  "api.message.ddd2b8b4d7bd": "यह सहेजा संस्करण पहले से लंबित या अनुमोदित है।",
  "api.message.a05cf5bf7750": "भेजने के लिए टिप्पणी जोड़ें (अधिकतम 4000 अक्षर)।",
  "api.message.aee0ef72de4e": "1–100 अलग रिकॉर्ड चुनें और निर्णय की टिप्पणी जोड़ें।",
  "api.message.49cb9760a23d": "अधिकतम 100 सूचनाएँ चुनें।",
  "api.message.0368f2f2c447": "अज्ञात अनुमोदन कार्रवाई।",
  "api.message.1d8e33865ae3": "अमान्य आयात अनुरोध।",
  "api.message.4702e2ea89c6": "उत्पाद और पृष्ठ चुनें।",
  "api.message.7cfa1d1c6fe6": "आपकी भूमिका को रिकॉर्ड आयात करने की अनुमति नहीं है।",
  "api.message.23461961caf0": "वैध आयात पहचानकर्ता आवश्यक है।",
  "api.message.6f6495173490": "इस पृष्ठ के लिए आयात परिभाषा नहीं है।",
  "api.message.e4bbf47958bf": "1–500 मैप की गई पंक्तियाँ दें; हर सेल अधिकतम 4000 अक्षर का हो।",
  "api.message.2a46ded27457": "यह आयात पहचानकर्ता पहले उपयोग हो चुका है।",
  "api.message.9a2e0adf7846": "नया आयात बनाने से पहले पिछले आयात पूरे करें या दोबारा चलाएँ।",
  "api.message.f5003afb7710": "अज्ञात आयात कार्रवाई।",
  "api.message.6799f06939d9": "आयात उपलब्ध नहीं है।",
  "api.message.c5d68aa099de": "आयात परिभाषा अब उपलब्ध नहीं है।",
  "api.message.0b3462597a97": "उत्पाद, पृष्ठ और सहेजा रिकॉर्ड आवश्यक हैं।",
  "api.message.4a8d45c019e6": "संलग्नक अब उपलब्ध नहीं है।",
  "api.message.78430f3b7add": "आपकी भूमिका को रिकॉर्ड पैनल बदलने की अनुमति नहीं है।",
  "api.message.7415683b1fc3": "कार्रवाई पहचानकर्ता दूसरे बदलाव में उपयोग हो चुका है।",
  "api.message.b319e42985cd": "1–4000 अक्षरों की टिप्पणी लिखें।",
  "api.message.b300d15ae4d4": "यह डेमो हर रिकॉर्ड पर 200 टिप्पणियाँ स्वीकार करता है।",
  "api.message.f7dbb8f02013": "अमान्य संलग्नक।",
  "api.message.6f38216914c3": "1 बाइट से 2 MB तक की फ़ाइल चुनें।",
