  "template.clinical.guideApi": "ClinicalPatientWorkspace को ClinicalTemplateAdapter दें। डेमो एडाप्टर प्रमाणित clinical-templates एंडपॉइंट उपयोग करता है; डेटा और फ़ॉर्म मेटाडेटा API से आते हैं।",
