  "template.comprehensive.confirmHint": "प्रमाणित खाते से डेमो रिकॉर्ड अंतिम करें। यह केवल पढ़ने योग्य होगा। आदेश प्रेषित या प्रमाणित डिजिटल हस्ताक्षर नहीं होंगे।",
