  "template.comprehensive.discardHint": "बदलाव रखने के लिए ड्राफ्ट सहेजें। आगे बढ़ने पर केवल बिना सहेजा इनपुट हटेगा; सहेजे परामर्श उपलब्ध रहेंगे।",
