  "designer.dependencyInvalid": "ड्रॉपडाउन निर्भरताएँ जाँचें: प्रत्येक अधीन विकल्प को मौजूद मूल मान से जोड़ें। मूल फ़ील्ड ड्रॉपडाउन होना चाहिए; चक्र और पाँच स्तर से गहरी शृंखलाएँ मान्य नहीं हैं।",
  "designer.chooseParent": "पहले मान्य मूल विकल्प चुनें।",
  "designer.lookupError": "विकल्प लोड नहीं हुए। आगे बढ़ने के लिए पुनः प्रयास करें।",
