  "You do not have access to that report. Ask an administrator if you need it.": "आपके पास उस रिपोर्ट तक पहुंच नहीं है। यदि आपको इसकी आवश्यकता है तो व्यवस्थापक से पूछें।",
  "You get one attempt. Answers and explanations are shown after you submit.": "आपको एक प्रयास मिलता है। सबमिट करने के बाद उत्तर और स्पष्टीकरण दिखाए जाते हैं।",
