  "MockIns exchange supports AED, USD, EUR and INR. Currency conversion is not performed.": "MockIns एक्सचेंज AED, USD, EUR और INR का समर्थन करता है। मुद्रा रूपांतरण नहीं किया जाता है।",
  "MockIns supports AED, USD, EUR and INR. No FX conversion is applied.": "MockIns, AED, USD, EUR और INR का समर्थन करता है। कोई FX रूपांतरण लागू नहीं किया जाता है।",
  "No payer receivable remains for replacement.": "प्रतिस्थापन के लिए कोई भुगतानकर्ता प्राप्य शेष नहीं है।",
