  "Only an unsent exchange can be cancelled. Reconcile uncertain provider outcomes.": "केवल एक अप्रेषित विनिमय रद्द किया जा सकता है। अनिश्चित प्रदाता परिणामों का समाधान करें।",
  "Only branch policies can inherit tenant defaults.": "केवल शाखा नीतियां ही टेनेंट डिफ़ॉल्ट इनहेरिट कर सकती हैं।",
