  "Prior payer evidence changed after queuing. Reconcile coordination before submitting.": "कतारबद्ध करने के बाद पूर्व भुगतानकर्ता साक्ष्य बदल गया। प्रस्तुत करने से पहले समन्वय का समाधान करें।",
  "Prior payer evidence changed after submission. Reconcile the coordination correction before posting.": "प्रस्तुत करने के बाद पूर्व भुगतानकर्ता साक्ष्य बदल गया। पोस्ट करने से पहले समन्वय सुधार का समाधान करें।",
