  "The branch uses the effective tenant payer defaults from this date.": "यह शाखा इस तिथि से प्रभावी टेनेंट भुगतानकर्ता डिफ़ॉल्ट का उपयोग करती है।",
  "Unknown synthetic collection scenario.": "अज्ञात सिंथेटिक संग्रहण परिदृश्य।",
