  "Freeze the prior revision and prepare a new submission revision for the remaining payer liability.": "पिछले संशोधन को स्थिर करें और भुगतानकर्ता की शेष देयता के लिए नया सबमिशन संशोधन तैयार करें।",
  "Only an unsent queued exchange can be cancelled. Reconcile uncertain provider outcomes.": "केवल कतार में रखा गया, न भेजा गया एक्सचेंज रद्द किया जा सकता है। प्रदाता के अनिश्चित परिणामों का मिलान करें।",
