  "api.message.791b8e030b17": "इलेक्ट्रॉनिक समन्वय के लिए एक पोस्ट की गई पूर्व प्रेषण या अस्वीकृति सूचना आवश्यक है। केवल इनटेक अस्वीकृति EOB साक्ष्य नहीं है।",
  "api.message.bfb590f29762": "केवल एक अप्रेषित विनिमय रद्द किया जा सकता है। अनिश्चित प्रदाता परिणामों का समाधान करें।",
  "api.message.dde7bacc9be5": "कतारबद्ध करने के बाद पूर्व भुगतानकर्ता साक्ष्य बदल गया। प्रस्तुत करने से पहले समन्वय का समाधान करें।",
